import std.io
import std.collections

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let s = collections.setOf([1, 2])
    s.add(3)
    io.println("has3:${s.has(3)}")
    io.println("has9:${s.has(9)}")
    io.println("rm2:${s.remove(2)}")
    io.println("rm2again:${s.remove(2)}")
    io.println("ssize:${s.size()}")
    return Ok(())
}
